ORDER_NOT_FOUND = "order_not_found"
DUPLICATE_ACCEPTANCE = "duplicate_acceptance"
EXCEEDS_REFUNDABLE = "exceeds_refundable_balance"
DUPLICATE_LINE = "duplicate_line"

