    INVALID_AMOUNT: "amount_cents must be a positive integer",
    ORDER_NOT_FOUND: "order not found",
    DUPLICATE_ACCEPTANCE: "refund already accepted",
    EXCEEDS_REFUNDABLE: "refund exceeds refundable balance",
