        "refund_id": row["refund_id"],
        "conclusion": row["conclusion"],
    }
    # 提交金额为合法整数时回显整数，否则回显原始字符串
    raw = row["amount_raw"]
    try:
        line["amount_cents"] = int(raw)
    except ValueError:
        line["amount_cents"] = raw
    if row["reason"]:
        line["reason"] = row["reason"]
        line["detail"] = REASON_DETAIL[row["reason"]]
    return line


def _load_batch(conn: sqlite3.Connection, tenant: str, request_id: str) -> sqlite3.Row | None:
    return conn.execute(
