                        "order_not_found": ORDER_NOT_FOUND,
                        "duplicate_refund": DUPLICATE_ACCEPTANCE,
                        "exceeds_refundable_balance": EXCEEDS_REFUNDABLE,
                    }[reason]
                    record(idx, order_id, refund_id, amount, REJECTED, code)

